import{_ as o,r as i,o as s,c as l,b as e,d,a as r,e as h,w as c}from"./app-84ed3530.js";const b={},p={href:"https://github.com/VanGong1999/FDE",target:"_blank",rel:"noopener noreferrer"},g={href:"https://www.tryexponent.com/blog/forward-deployed-engineer-interview-the-definitive-2026-guide-fde",target:"_blank",rel:"noopener noreferrer"},u={href:"https://www.theforwarddeployed.io/",target:"_blank",rel:"noopener noreferrer"};function k(x,t){const a=i("ExternalLinkIcon"),n=i("RouterLink");return s(),l("div",null,[t[9]||(t[9]=e("h1",{id:"fde-面试通关-全景、框架与公司对照",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#fde-面试通关-全景、框架与公司对照","aria-hidden":"true"},"#"),d(" FDE 面试通关：全景、框架与公司对照")],-1)),e("blockquote",null,[e("p",null,[t[3]||(t[3]=d("本文整理自开源知识库 ",-1)),e("a",p,[t[0]||(t[0]=d("VanGong1999/FDE",-1)),r(a)]),t[4]||(t[4]=d("（MIT License）的「面试通关」部分，综合 ",-1)),e("a",g,[t[1]||(t[1]=d("Exponent FDE Interview Guide 2026",-1)),r(a)]),t[5]||(t[5]=d("、",-1)),e("a",u,[t[2]||(t[2]=d("The Forward Deployed",-1)),r(a)]),t[6]||(t[6]=d(" 与各公司公开招聘信息。",-1))])]),t[10]||(t[10]=h(`<p>FDE 面试不是标准后端 LeetCode 流水线，而是 <strong>工程能力 × 问题拆解 × 客户判断 ×（常有）AI 生产化</strong> 的组合。</p><blockquote><p>轮次随团队/年份变化，<strong>以招聘官邮件为准</strong>。以下为公开报道与社区信息的综合画像（约 2025–2026），薪酬数字为 Levels.fyi 自报数据，仅供方向参考。</p></blockquote><hr><h2 id="_1-面试全景-轮次与考点" tabindex="-1"><a class="header-anchor" href="#_1-面试全景-轮次与考点" aria-hidden="true">#</a> 1. 面试全景：轮次与考点</h2><div class="language-mermaid line-numbers-mode" data-ext="mermaid"><pre class="language-mermaid"><code><span class="token keyword">flowchart</span> LR
  R<span class="token text string">[&quot;Recruiter&lt;br/&gt;动机筛查&quot;]</span> <span class="token arrow operator">--&gt;</span> T<span class="token text string">[&quot;技术面 / Take-home&quot;]</span>
  T <span class="token arrow operator">--&gt;</span> L<span class="token text string">[&quot;Onsite 多轮&quot;]</span>
  L <span class="token arrow operator">--&gt;</span> H<span class="token text string">[&quot;HM / 价值观&quot;]</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>轮次类型</th><th>考什么</th><th>你要展示</th></tr></thead><tbody><tr><td>Recruiter</td><td>动机、前线意愿、沟通</td><td>清晰故事：为何 FDE</td></tr><tr><td>Coding</td><td>实用工程</td><td>正确、可读、沟通</td></tr><tr><td>Decomposition</td><td>模糊问题拆解</td><td>用户/指标/硬点/下一步</td></tr><tr><td>Learning</td><td>陌生代码库</td><td>快速变有用</td></tr><tr><td>System / LLM Design</td><td>方案</td><td>约束、eval、rollout</td></tr><tr><td>Take-home</td><td>作品 + 演示</td><td>生产形完整度</td></tr><tr><td>Behavioral</td><td>所有权与冲突</td><td>STAR + 结果</td></tr><tr><td>HM / Values</td><td>匹配度</td><td>诚实、使命、判断</td></tr></tbody></table><h3 id="常见淘汰原因" tabindex="-1"><a class="header-anchor" href="#常见淘汰原因" aria-hidden="true">#</a> 常见淘汰原因</h3><ul><li>一上来堆功能，不定义用户与指标</li><li>Demo 思维，无 eval/权限/成本</li><li>不会推回（push back），只会答应</li><li>编码沟通差或无法读他人代码</li><li>动机是「只想碰模型」而非交付结果</li></ul><hr><h2 id="_2-公司对照与备考权重" tabindex="-1"><a class="header-anchor" href="#_2-公司对照与备考权重" aria-hidden="true">#</a> 2. 公司对照与备考权重</h2><table><thead><tr><th>维度</th><th>Palantir FDSE</th><th>OpenAI FDE</th><th>Anthropic Applied AI</th><th>Google Cloud FDE</th><th>AI 初创</th></tr></thead><tbody><tr><td>资历要求</td><td>区间最宽（应届至资深）</td><td>5 年以上，端到端 ownership</td><td>3 年以上，MCP 原生</td><td>多职级</td><td>看具体 JD</td></tr><tr><td>编码强度</td><td>高</td><td>中（偏应用）</td><td>中</td><td>约 1/4 时间写码</td><td>中高</td></tr><tr><td>Decomposition</td><td><strong>极重要（招牌环节）</strong></td><td>重要</td><td>重要</td><td>重要</td><td>中</td></tr><tr><td>Take-home</td><td>较少作主线</td><td>常见</td><td>可能有</td><td>—</td><td>常见</td></tr><tr><td>LLM 深挖</td><td>视团队</td><td>很深</td><td>很深（安全/eval）</td><td>平台+AI</td><td>深</td></tr><tr><td>薪酬参考（Levels.fyi 自报）</td><td>中位 ~$201k</td><td>高于市场</td><td>高于市场</td><td>多档</td><td>波动大</td></tr></tbody></table><p>要点解读：</p><ul><li><strong>Palantir</strong>：FDSE 模式的发明者，面试以「问题拆解」为核心而非算法；资历区间最宽，是职业早期最敞开的门。其面试方法论资料最充分、最适合备考。</li><li><strong>OpenAI</strong>：要求最多经验，强调端到端 ownership——从 discovery、技术范围界定、系统设计到构建与生产上线，「进展依赖代码时」直接动手。</li><li><strong>Anthropic</strong>：明确要求交付用于生产的 <strong>MCP 服务器、子代理与 agent skills</strong>，强调 high agency 与驾驭模糊性。</li><li><strong>Google Cloud</strong>：同一个头衔横跨多个职级；「创始人思维」的实际含义是「没人给你规格说明，范围蔓延是你自己的问题」。</li><li><strong>初创公司</strong>：意味着「派到客户那里、什么都得干」，考察无结构约束下的全面性与 ownership。</li></ul><h3 id="按目标公司分配备面时间" tabindex="-1"><a class="header-anchor" href="#按目标公司分配备面时间" aria-hidden="true">#</a> 按目标公司分配备面时间</h3><table><thead><tr><th>目标</th><th>备面权重（示例）</th></tr></thead><tbody><tr><td>Palantir 向</td><td>拆解口述 30% · 实用编码（图/SQL）30% · 陌生代码库 20% · 行为面 20%</td></tr><tr><td>OpenAI 向</td><td>Take-home 级项目（eval+安全+成本+rollout）35% · RAG/Agent 深挖 25% · 方案设计 20% · 行为面 20%</td></tr><tr><td>Anthropic 向</td><td>LLM 系统设计（安全、HITL、审计）30% · Eval 与失败分析 25% · 编码 20% · 价值观 25%</td></tr></tbody></table><hr><h2 id="_3-decomposition-拆解面-标志性轮次" tabindex="-1"><a class="header-anchor" href="#_3-decomposition-拆解面-标志性轮次" aria-hidden="true">#</a> 3. Decomposition 拆解面（标志性轮次）</h2><p>面试官给出模糊、常被「伪造成解决方案」的业务诉求（「给我们做一个员工 ChatGPT」），考你能否在压力下结构化拆解。</p><h3 id="五步框架" tabindex="-1"><a class="header-anchor" href="#五步框架" aria-hidden="true">#</a> 五步框架</h3><table><thead><tr><th>步</th><th>动作</th><th>合格样子</th></tr></thead><tbody><tr><td>1</td><td><strong>用户与结果</strong></td><td>先说清为谁、被什么指标衡量；不先谈 App/Chatbot</td></tr><tr><td>2</td><td><strong>假设与范围</strong></td><td>大声假设并向面试官确认；划出非目标</td></tr><tr><td>3</td><td><strong>拆子问题</strong></td><td>3–5 个<strong>问题部件</strong>（不是「调研→开发→上线」这种阶段）</td></tr><tr><td>4</td><td><strong>硬点</strong></td><td>指出做错会让结果崩掉的那块，并辩护为何硬</td></tr><tr><td>5</td><td><strong>具体下一步</strong></td><td>可执行、可证伪；说明如何知道自己错了</td></tr></tbody></table><h3 id="开场-60-秒脚本-练到不看稿" tabindex="-1"><a class="header-anchor" href="#开场-60-秒脚本-练到不看稿" aria-hidden="true">#</a> 开场 60 秒脚本（练到不看稿）</h3><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>我想先确认用户和成功标准，再拆问题。
我假设……——这样合理吗？
在此基础上，我会避免……（非目标）。
关键子问题是：1… 2… 3…
其中最硬的是……因为……
我下一步会……；若看到……说明假设错了。
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="扣分最快的行为" tabindex="-1"><a class="header-anchor" href="#扣分最快的行为" aria-hidden="true">#</a> 扣分最快的行为</h3><p>第一分钟就聊技术栈 · 长时间「架构」却无任何具体物 · 子问题写成项目管理阶段 · 硬点说成「需要微服务」这类空话 · 等面试官问才说如何验证。</p><h3 id="练习题-每题限时-8–10-分钟口述-录音自评" tabindex="-1"><a class="header-anchor" href="#练习题-每题限时-8–10-分钟口述-录音自评" aria-hidden="true">#</a> 练习题（每题限时 8–10 分钟口述 + 录音自评）</h3><ol><li>「给我们做一个员工 ChatGPT。」→ 硬点常是<strong>权限与过期知识</strong></li><li>「用 AI 做智能客服，下周要上。」→ 先问指标是首响还是一次解决率；影子模式起步</li><li>「把所有合同自动审核掉。」→ 拆条款类型；高风险条款必须 HITL</li><li>「做一个销售预测仪表盘。」→ 伪造成解决方案；先问谁的决策、预测周期</li><li>「老板要生成式 BI，人人用自然语言查数。」→ 硬点是 Text-to-SQL 的正确性与权限</li></ol><hr><h2 id="_4-c-a-s-e-框架与-delta" tabindex="-1"><a class="header-anchor" href="#_4-c-a-s-e-框架与-delta" aria-hidden="true">#</a> 4. C.A.S.E. 框架与 Delta</h2><p>接到系统设计/案例题，先别写码：</p><table><thead><tr><th>步</th><th>英文</th><th>做什么</th></tr></thead><tbody><tr><td><strong>C</strong></td><td>Clarify</td><td>数据量、安全（PII/PHI）、Definition of Done</td></tr><tr><td><strong>A</strong></td><td>Architect</td><td>从源系统到用户界面的数据流</td></tr><tr><td><strong>S</strong></td><td>Solve (<strong>Delta</strong>)</td><td>产品开箱缺什么，胶水如何补</td></tr><tr><td><strong>E</strong></td><td>Evaluate</td><td>如何证明不幻觉、如何监控</td></tr></tbody></table><p><strong>Delta</strong> 是 Palantir 语境里的核心概念：产品（Dev）之外，让它在客户场景真正跑起来所缺的那部分工程（Delta）——集成、权限、数据管道、评测、变更管理。面试官想听你说清「<strong>这个场景下 Delta 是什么</strong>」。</p><h3 id="示例-医院再入院预测-30-天叙事" tabindex="-1"><a class="header-anchor" href="#示例-医院再入院预测-30-天叙事" aria-hidden="true">#</a> 示例：医院再入院预测（30 天叙事）</h3><p><strong>情景</strong>：医院集团要用软件预测再入院；二十年 on-prem SQL Server；零云；极强 HIPAA 合规。</p><table><thead><tr><th>阶段</th><th>动作</th></tr></thead><tbody><tr><td>Day 1–7</td><td>数据画像；与 CMO 定义「再入院」窗口；与感到被威胁的 IT 建信任</td></tr><tr><td>Day 8–15</td><td>Landing Zone：对象存储摄入 + 仓存储；脱敏方案满足 HIPAA</td></tr><tr><td>Day 16–25</td><td>检索/Agent 接地病史；<strong>Delta</strong>：实时生命体征接入更新预测</td></tr><tr><td>Day 26–30</td><td>对照历史结局做评测；5 名医生 UAT——行为没改变则项目失败</td></tr></tbody></table><h3 id="评分自检-每题后打勾-缺两项以上重录" tabindex="-1"><a class="header-anchor" href="#评分自检-每题后打勾-缺两项以上重录" aria-hidden="true">#</a> 评分自检（每题后打勾，缺两项以上重录）</h3><ul><li><input type="checkbox" class="task-checkbox" disabled> 开场 60 秒内澄清成功标准与约束</li><li><input type="checkbox" class="task-checkbox" disabled> 画出数据/控制流（哪怕方框）</li><li><input type="checkbox" class="task-checkbox" disabled> 明确说出 <strong>Delta</strong>（产品缺什么）</li><li><input type="checkbox" class="task-checkbox" disabled> 提到安全或合规至少一点</li><li><input type="checkbox" class="task-checkbox" disabled> 提到如何证明有效（Eval/UAT/指标）</li><li><input type="checkbox" class="task-checkbox" disabled> 提到采用或干系人至少一点</li><li><input type="checkbox" class="task-checkbox" disabled> 有意说了「非目标」或分阶段</li></ul><hr><h2 id="_5-行为面-star-与「推回」" tabindex="-1"><a class="header-anchor" href="#_5-行为面-star-与「推回」" aria-hidden="true">#</a> 5. 行为面：STAR 与「推回」</h2><p>行为面考所有权与冲突处理。高频题：</p><ul><li>为何选择 FDE？（答案要落在「对客户结果负责」，不是「想接触新模型」）</li><li>讲一次你说服客户放弃原始需求 / 对客户说不的经历</li><li>讲一次最严重的事故与你的处理</li><li>长期出差/驻场你能接受吗？</li><li>客户说「差不多就行」怎么回应？（用「校准式诚信」：明确说清当前准确率、与目标的差距、达成路径）</li></ul><p>准备方法：把经历写成 STAR（情境-任务-行动-结果），<strong>结果必须量化</strong>，且至少一个故事含「推回范围」或「敌意干系人」。</p><hr><h2 id="_6-简历法则" tabindex="-1"><a class="header-anchor" href="#_6-简历法则" aria-hidden="true">#</a> 6. 简历法则</h2><p>Bullet 结构：<strong>拥有的行动 + 困难环境 + 工程决策 + 可衡量的结果</strong>。</p><table><thead><tr><th>弱写法</th><th>强写法</th></tr></thead><tbody><tr><td>用 Python 和向量数据库构建了一个 RAG 聊天机器人</td><td>为 60 名分析师交付权限感知的研究助手；建立检索评测并把失败搜索减少 31%</td></tr><tr><td>与客户合作收集需求</td><td>把客户要求的仪表盘重构为异常工作流，与两名操作员试点，人工复核时间减少 22%</td></tr><tr><td>改进应用性能</td><td>在固定预算下引入缓存与模型路由，p95 延迟降低 41%，单任务成本降低 28%</td></tr></tbody></table><p>删掉：没有支撑的形容词、庞大工具清单、挤掉「已交付工作」的课程作业。<strong>关键词帮你被发现，证据帮你赢下面试。</strong></p><h3 id="_4–6-周备面计划-速查" tabindex="-1"><a class="header-anchor" href="#_4–6-周备面计划-速查" aria-hidden="true">#</a> 4–6 周备面计划（速查）</h3><table><thead><tr><th>周</th><th>动作</th></tr></thead><tbody><tr><td>1</td><td>角色认知 + 自评；定 1 个主目标公司类型；改简历</td></tr><tr><td>2</td><td>Decomposition 每日 1 题口述；补编码底线</td></tr><tr><td>3</td><td>LLM/RAG/Eval 深挖问答；做一个可演示的小项目</td></tr><tr><td>4–5</td><td>按目标公司权重刷对应轮次；Take-home 级项目收尾</td></tr><tr><td>6</td><td>模拟面试（AI 当面试官）；90 秒自我介绍录音打磨</td></tr></tbody></table><hr><h2 id="_7-recruiter-电话-90-秒标准题" tabindex="-1"><a class="header-anchor" href="#_7-recruiter-电话-90-秒标准题" aria-hidden="true">#</a> 7. Recruiter 电话：90 秒标准题</h2><ol><li>自我介绍（背景 → 客户/结果经历 → 为何 FDE）</li><li>为何本公司（产品 + 前线模式 + 你的匹配）</li><li>能否出差/驻场</li><li>薪资区间（按你的策略）</li><li>最近项目深挖预告（留钩子）</li></ol><hr><h2 id="_8-读完马上做" tabindex="-1"><a class="header-anchor" href="#_8-读完马上做" aria-hidden="true">#</a> 8. 读完马上做</h2><ul><li><input type="checkbox" class="task-checkbox" disabled> 选定 1 个主目标公司类型，按 §2 分配下周备面时间</li><li><input type="checkbox" class="task-checkbox" disabled> 写 90 秒自我介绍并录音</li><li><input type="checkbox" class="task-checkbox" disabled> 对 §3 练习题任选 1 题，限时 8 分钟口述并按五步自评</li><li><input type="checkbox" class="task-checkbox" disabled> 把简历最强的一条改写成「结果句」</li></ul>`,54)),e("p",null,[t[8]||(t[8]=d("姊妹篇：",-1)),r(n,{to:"/blogs/ai-jobs/agent-04-interview.html"},{default:c(()=>[...t[7]||(t[7]=[d("全栈 AI Agent 工程师面试高频题",-1)])]),_:1})])])}const m=o(b,[["render",k],["__file","fde-04-interview.html.vue"]]);export{m as default};
